-- FaceFIT Supabase/PostgreSQL schema. Run this before importing legacy MySQL data.
CREATE TABLE IF NOT EXISTS users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  full_name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL, phone VARCHAR(30), profile_image_path VARCHAR(500),
  role VARCHAR(20) NOT NULL DEFAULT 'customer' CHECK (role IN ('customer','stylist','owner','admin')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS customer_profiles (
  user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, hair_type VARCHAR(50), hair_length VARCHAR(50), hair_texture VARCHAR(50),
  style_preference VARCHAR(10) NOT NULL DEFAULT 'men' CHECK (style_preference IN ('men','women')), updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS salons (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
  name VARCHAR(150) NOT NULL, description TEXT, address VARCHAR(255) NOT NULL, city VARCHAR(100) NOT NULL,
  latitude NUMERIC(10,7), longitude NUMERIC(10,7), phone VARCHAR(30), website VARCHAR(500), profile_image_path VARCHAR(500),
  source VARCHAR(50), external_id VARCHAR(100), source_url VARCHAR(500), rating NUMERIC(2,1) NOT NULL DEFAULT 0,
  opening_time TIME, closing_time TIME, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (source, external_id)
);
CREATE TABLE IF NOT EXISTS stylists (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
  salon_id BIGINT NOT NULL REFERENCES salons(id) ON DELETE CASCADE, specialties VARCHAR(255), description VARCHAR(500),
  is_available BOOLEAN NOT NULL DEFAULT TRUE, image_path VARCHAR(500), deleted_at TIMESTAMPTZ
);
CREATE TABLE IF NOT EXISTS services (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, salon_id BIGINT NOT NULL REFERENCES salons(id) ON DELETE CASCADE,
  name VARCHAR(150) NOT NULL, description TEXT, price NUMERIC(10,2) NOT NULL, duration_minutes SMALLINT NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE, deleted_at TIMESTAMPTZ
);
CREATE TABLE IF NOT EXISTS salon_hairstyles (
  salon_id BIGINT NOT NULL REFERENCES salons(id) ON DELETE CASCADE, hairstyle_name VARCHAR(120) NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (salon_id, hairstyle_name)
);
CREATE TABLE IF NOT EXISTS bookings (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  service_id BIGINT NOT NULL REFERENCES services(id) ON DELETE RESTRICT, stylist_id BIGINT REFERENCES stylists(id) ON DELETE SET NULL,
  appointment_at TIMESTAMP NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','confirmed','completed','cancelled')),
  notes VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS face_analyses (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  face_shape VARCHAR(50) NOT NULL, confidence NUMERIC(5,2), image_url VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS saved_hairstyles (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  hairstyle_name VARCHAR(120) NOT NULL, saved_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (user_id, hairstyle_name)
);
CREATE TABLE IF NOT EXISTS favorite_salons (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, salon_id BIGINT NOT NULL REFERENCES salons(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (user_id, salon_id));
CREATE TABLE IF NOT EXISTS notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(150) NOT NULL, message VARCHAR(500) NOT NULL, destination VARCHAR(50), reference_id BIGINT, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, salon_id BIGINT NOT NULL REFERENCES salons(id) ON DELETE CASCADE, rating SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5), comment VARCHAR(500), image_path VARCHAR(500), owner_reply VARCHAR(1000), owner_replied_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS salon_portfolio_images (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, salon_id BIGINT NOT NULL REFERENCES salons(id) ON DELETE CASCADE, image_path VARCHAR(500) NOT NULL, caption VARCHAR(200), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS review_replies (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, review_id BIGINT NOT NULL REFERENCES reviews(id) ON DELETE CASCADE, owner_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, message VARCHAR(1000), image_path VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS privacy_settings (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, notifications_enabled BOOLEAN NOT NULL DEFAULT TRUE, save_scan_history BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS booking_deposits (booking_id BIGINT PRIMARY KEY REFERENCES bookings(id) ON DELETE CASCADE, amount NUMERIC(10,2) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'unpaid' CHECK (status IN ('unpaid','submitted','verified','rejected')), reference VARCHAR(30) UNIQUE, receipt TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS booking_changes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, booking_id BIGINT NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, requested_at TIMESTAMP NOT NULL, reason VARCHAR(500) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS booking_queue (booking_id BIGINT PRIMARY KEY REFERENCES bookings(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stylist_settings (stylist_id BIGINT PRIMARY KEY REFERENCES stylists(id) ON DELETE CASCADE, settings JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS stylist_booking_details (booking_id BIGINT PRIMARY KEY REFERENCES bookings(id) ON DELETE CASCADE, context JSONB, stage VARCHAR(20) NOT NULL DEFAULT 'scheduled', stage_slot TIMESTAMP);
CREATE TABLE IF NOT EXISTS stylist_portfolio (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, stylist_id BIGINT NOT NULL REFERENCES stylists(id) ON DELETE CASCADE, caption VARCHAR(300) NOT NULL, image_data TEXT NOT NULL, consent_at TIMESTAMP NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stylist_reviews (booking_id BIGINT PRIMARY KEY REFERENCES bookings(id) ON DELETE CASCADE, rating SMALLINT NOT NULL, comment VARCHAR(1000) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS appointment_tracking (booking_id BIGINT NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, appointment_at TIMESTAMP NOT NULL, arrived_at TIMESTAMP, reminder_sent BOOLEAN NOT NULL DEFAULT FALSE, due_sent BOOLEAN NOT NULL DEFAULT FALSE, auto_cancelled BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY (booking_id, appointment_at));
CREATE INDEX IF NOT EXISTS idx_salons_city_active ON salons(city, is_active);
CREATE INDEX IF NOT EXISTS idx_services_salon_active ON services(salon_id, is_active);
CREATE INDEX IF NOT EXISTS idx_bookings_user_date ON bookings(user_id, appointment_at);
CREATE INDEX IF NOT EXISTS idx_bookings_stylist_date ON bookings(stylist_id, appointment_at);
CREATE INDEX IF NOT EXISTS idx_reviews_user_salon ON reviews(user_id, salon_id);
CREATE INDEX IF NOT EXISTS idx_review_replies_review ON review_replies(review_id, created_at);
